#define DMCTP_INSTRUCTION_COUNT (sizeof(dmctp_instruction_table) / sizeof(dmctp_instruction_table[0]))

static inline uint32_t dmctp_field(uint32_t inst, unsigned lsb, unsigned width)
{
    return (inst >> lsb) & (uint32_t)((UINT64_C(1) << width) - 1u);
}

static inline uint32_t dmctp_inst_opcode(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_OPCODE_LSB, DMCTP_FIELD_OPCODE_WIDTH);
}

static inline uint32_t dmctp_inst_rd(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_RD_LSB, DMCTP_FIELD_RD_WIDTH);
}

static inline uint32_t dmctp_inst_funct3(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_FUNCT3_LSB, DMCTP_FIELD_FUNCT3_WIDTH);
}

static inline uint32_t dmctp_inst_rs1(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_RS1_LSB, DMCTP_FIELD_RS1_WIDTH);
}

static inline uint32_t dmctp_inst_rs2(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_RS2_LSB, DMCTP_FIELD_RS2_WIDTH);
}

static inline uint32_t dmctp_inst_funct7(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_FUNCT7_LSB, DMCTP_FIELD_FUNCT7_WIDTH);
}

static inline uint32_t dmctp_inst_funct6(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_FUNCT6_LSB, DMCTP_FIELD_FUNCT6_WIDTH);
}

static inline uint32_t dmctp_inst_funct2(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_FUNCT2_LSB, DMCTP_FIELD_FUNCT2_WIDTH);
}

static inline uint32_t dmctp_inst_rs3(uint32_t inst)
{
    return dmctp_field(inst, DMCTP_FIELD_RS3_LSB, DMCTP_FIELD_RS3_WIDTH);
}

static inline int64_t dmctp_sign_extend(uint64_t value, unsigned width)
{
    const uint64_t sign = UINT64_C(1) << (width - 1u);
    return (int64_t)((value ^ sign) - sign);
}

static inline uint64_t dmctp_uimm_I(uint32_t inst)
{
    return ((uint64_t)dmctp_field(inst, 20u, 12u) << 0u);
}

static inline int64_t dmctp_imm_I(uint32_t inst)
{
    const uint64_t value = dmctp_uimm_I(inst);
    return dmctp_sign_extend(value, 12u);
}

static inline uint64_t dmctp_uimm_S(uint32_t inst)
{
    return ((uint64_t)dmctp_field(inst, 7u, 5u) << 0u) | ((uint64_t)dmctp_field(inst, 25u, 7u) << 5u);
}

static inline int64_t dmctp_imm_S(uint32_t inst)
{
    const uint64_t value = dmctp_uimm_S(inst);
    return dmctp_sign_extend(value, 12u);
}

static inline uint64_t dmctp_uimm_B(uint32_t inst)
{
    return ((uint64_t)dmctp_field(inst, 8u, 4u) << 1u) | ((uint64_t)dmctp_field(inst, 25u, 6u) << 5u) | ((uint64_t)dmctp_field(inst, 7u, 1u) << 11u) | ((uint64_t)dmctp_field(inst, 31u, 1u) << 12u);
}

static inline int64_t dmctp_imm_B(uint32_t inst)
{
    const uint64_t value = dmctp_uimm_B(inst);
    return dmctp_sign_extend(value, 13u);
}

static inline uint64_t dmctp_uimm_U(uint32_t inst)
{
    return ((uint64_t)dmctp_field(inst, 12u, 20u) << 12u);
}

static inline int64_t dmctp_imm_U(uint32_t inst)
{
    const uint64_t value = dmctp_uimm_U(inst);
    return dmctp_sign_extend(value, 32u);
}

static inline uint64_t dmctp_uimm_J(uint32_t inst)
{
    return ((uint64_t)dmctp_field(inst, 21u, 10u) << 1u) | ((uint64_t)dmctp_field(inst, 20u, 1u) << 11u) | ((uint64_t)dmctp_field(inst, 12u, 8u) << 12u) | ((uint64_t)dmctp_field(inst, 31u, 1u) << 20u);
}

static inline int64_t dmctp_imm_J(uint32_t inst)
{
    const uint64_t value = dmctp_uimm_J(inst);
    return dmctp_sign_extend(value, 21u);
}

static inline const dmctp_instruction_desc_t *dmctp_decode(uint32_t inst)
{
    size_t i;
    for (i = 0; i < DMCTP_INSTRUCTION_COUNT; ++i) {
        const dmctp_instruction_desc_t *desc = &dmctp_instruction_table[i];
        if ((inst & desc->mask) == desc->match) return desc;
    }
    return NULL;
}

